public class TrendView:FrameworkElement {
 public readonly List<SystemSample> Samples=new List<SystemSample>();public string Series="cpu";public TrendView(){Height=160;MinWidth=100;}
 protected override void OnRender(DrawingContext dc){base.OnRender(dc);double w=ActualWidth,h=ActualHeight;for(int i=0;i<5;i++)dc.DrawLine(new Pen((TryFindResource("DeskLine") as Brush??TerminalStyle.BrushOf("#254051")),.5),new Point(0,i*h/4),new Point(w,i*h/4));if(Samples.Count<2)return;
  Draw(dc,w,h,Series=="network"?"download":Series,TryFindResource("DeskAccent") as Brush??TerminalStyle.Cyan);if(Series=="network")Draw(dc,w,h,"upload",TerminalStyle.BrushOf("#E6BD7F"));
 }
 double? Value(SystemSample s,string type){return type=="cpu"?s.Cpu:type=="gpu"?s.Gpu:type=="download"?s.Download:s.Upload;}
 void Draw(DrawingContext dc,double w,double h,string type,Brush color){
  double max=100;if(type=="download"||type=="upload")max=Math.Max(1024,Samples.Max(s=>Math.Max(s.Download??0,s.Upload??0))*1.15);double start=Samples.First().Utc.Ticks,end=Samples.Last().Utc.Ticks;Point? previous=null;DateTime previousUtc=DateTime.MinValue;
  foreach(var sample in Samples){double? v=Value(sample,type);if(!v.HasValue){previous=null;continue;}var p=new Point((sample.Utc.Ticks-start)/Math.Max(1,end-start)*w,h-4-Math.Min(1,v.Value/max)*(h-8));if(previous.HasValue&&(sample.Utc-previousUtc).TotalSeconds<=15)dc.DrawLine(new Pen(color,2),previous.Value,p);previous=p;previousUtc=sample.Utc;}if(previous.HasValue)dc.DrawEllipse(color,null,previous.Value,3,3);
 }
 public void Add(SystemSample sample){if(sample==null||Samples.Count>0&&Samples.Last().Utc==sample.Utc)return;if(Samples.Count>0&&sample.Utc<Samples.Last().Utc)Samples.Clear();Samples.Add(sample);if(Samples.Count>60)Samples.RemoveAt(0);InvalidateVisual();}
}
public class MemoryRing:FrameworkElement {
 public double Percent;public MemoryRing(){Width=145;Height=145;}
 protected override void OnRender(DrawingContext dc){double r=53;Point c=new Point(72,72);dc.DrawEllipse(null,new Pen((TryFindResource("DeskLine") as Brush??TerminalStyle.BrushOf("#263F50")),12),c,r,r);double angle=Math.Max(0,Math.Min(99.99,Percent))/100*Math.PI*2;if(angle<=0)return;var end=new Point(72+Math.Sin(angle)*r,72-Math.Cos(angle)*r);var g=new StreamGeometry();using(var s=g.Open()){s.BeginFigure(new Point(72,19),false,false);s.ArcTo(end,new Size(r,r),0,angle>Math.PI,SweepDirection.Clockwise,true,false);}dc.DrawGeometry(null,new Pen((TryFindResource("DeskAccent") as Brush??TerminalStyle.BrushOf("#79D9C1")),12){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round},g);}
}
