 static Border Panel(string caption,string icon,out StackPanel body){body=new StackPanel();var heading=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,0,0,12)};heading.Children.Add(TerminalStyle.Icon(icon,24));heading.Children.Add(new TextBlock{Text=caption,FontSize=16,FontWeight=FontWeights.SemiBold,Foreground=TerminalStyle.Text,Margin=new Thickness(10,0,0,0),VerticalAlignment=VerticalAlignment.Center});body.Children.Add(heading);return new Border{Child=body,Background=TerminalStyle.Gradient("#182F40","#0A1B2B"),BorderBrush=TerminalStyle.BrushOf("#405E72"),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(10),Padding=new Thickness(16),Margin=new Thickness(0,0,0,14),Effect=new System.Windows.Media.Effects.DropShadowEffect{BlurRadius=18,ShadowDepth=3,Opacity=.10}};}
