 public void ShowPage(string name){if(name=="流量历史")name="线索档案馆";if(utilityNav!=null&&new[]{"便签","文本","剪贴板","桌面工具","语音与快捷键"}.Contains(name))utilityNav.IsExpanded=true;if(MemoAliases.Contains(name)){memoTab=name=="通知中心"?"系统通知":name;name="侦探备忘录";}monitorChecks.Clear();BeginNavigation(name);foreach(var element in new FrameworkElement[]{cpu,gpu,memory,network,gpuCaption,networkCaption,memoryCaption,status,memDetails,memValue,temperature,taskSummary,focusLabel,noticeSummary,modeLabel,footballStatus,trend,ring,focusProgress,bars,notices,nics,notificationStatus}){var panel=element.Parent as Panel;if(panel!=null)panel.Children.Remove(element);var decorator=element.Parent as Decorator;if(decorator!=null)decorator.Child=null;}page=name;ClearPinnedSettings();content.Children.Clear();content.Children.Add(backButton);
  string category=Category(name);foreach(var pair in navigation){pair.Value.Tag=null;pair.Value.SetResourceReference(Control.BackgroundProperty,pair.Key==name||!navigation.ContainsKey(name)&&pair.Key==category?"DeskSelected":"DeskSidebar");pair.Value.Opacity=pair.Key==name||!navigation.ContainsKey(name)&&pair.Key==category?1:.78;}
  AddPageHeading(name);if(name=="总览"||name=="性能监控")content.Children.Add(status);
