  if(name=="动作演示")BuildActionDemos();
  if(name=="数据与备份")BuildData();
  if(name=="启动与窗口")BuildStartup();
  if(name=="气泡外观")BuildBubbleAppearance();
  if(name=="线索档案馆")BuildTrafficHistoryPage();
  if(name=="监控与预警")BuildMonitorSettings();
