 static string Category(string name){if(name=="侦探备忘录"||MemoAliases.Contains(name))return "侦探备忘录";if(name=="监控与预警"||name=="任务栏外观"||name=="线索档案馆")return "性能监控";if(name=="气泡外观"||name=="原声配音"||name=="原声候选"||name=="动作演示")return "动作与移动";if(new[]{"文件搜索","证物卡","快捷入口","文件观察","磁盘与电池"}.Contains(name))return "文件与启动";if(new[]{"便签","文本","剪贴板","桌面工具","语音与快捷键","数据与备份"}.Contains(name))return "效率工具";if(new[]{"下班倒计时","待办计划","专注","提醒","健康"}.Contains(name))return "计划与专注";if(new[]{"Codex状态","进程监控","系统与网络"}.Contains(name))return "开发助手";if(name=="通知记录")return "通知中心";return name;}
