  var row=Columns(content,2);row.ColumnDefinitions[0].Width=new GridLength(1.6,GridUnitType.Star);StackPanel chart;var chartPanel=Panel("资源趋势","cpu",out chart);var actions=new WrapPanel();chart.Children.Add(actions);Button(actions,"CPU",()=>ChangeSeries("cpu"));Button(actions,"GPU",()=>ChangeSeries("gpu"));Button(actions,"上传 / 下载",()=>ChangeSeries("network"));chart.Children.Add(trend);chart.Children.Add(Text("最近60次真实采样 · CPU/GPU 0–100% · 网速自动量程\n青色：CPU/GPU/下载；金色：上传。断流时不连线。",11));Place(row,chartPanel,0);
